mapper.select:
select PARTNER_ID as partnerId, count(1) as totalNum, SUM(IF(IS_FILING='是',1,0)) as filingNum, 0 as unFilingNum, 0 as filingRate from BIZ_CRM_HETONG where DELETE_FLAG = 'NOT_DELETE' and STATUS = '1'
and PARTNER_TYPE = #{partnerType}
and PARTNER_ID is not null and PARTNER_ID != '' and SEAL_DATE >= #{startDate} and SEAL_DATE <= #{endDate} group by PARTNER_ID

select PARTNER_ID as partnerId, count(1) as threeUnFilingNum from BIZ_CRM_HETONG where DELETE_FLAG = 'NOT_DELETE' and STATUS = '1'
and PARTNER_TYPE = #{partnerType}
and PARTNER_ID is not null and PARTNER_ID != '' and (IS_FILING is null or IS_FILING = '' or IS_FILING != '是' ) and SEAL_DATE >= #{startDate} and SEAL_DATE <= #{endDate} and DATE_ADD(SEAL_DATE,INTERVAL 3 MONTH) < now() group by PARTNER_ID
